using System.Collections.Immutable;
using System.Globalization;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Testing;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;
using Microsoft.NET.Sdk.Razor.SourceGenerators;

namespace Ducky.Generators.Tests.Infrastructure;

// DUCKY009 verifier tests (SPEC §16.2): AnalyzerVerifier's CSharpAnalyzerTest with the real Razor source generator in the
// driver, so markup reaches the analyzer only as `<auto-generated>` Razor output with its #line directives, exactly as in
// a consumer build. The .razor files are additional files and the options are the ones the Razor SDK writes to the
// generated .editorconfig. Compiler warnings count too, so a test never passes on markup that wouldn't build clean.
internal static class RazorVerifier<TAnalyzer>
    where TAnalyzer : DiagnosticAnalyzer, new()
{
    // Microsoft.AspNetCore.Components.Web and what it references, as a Razor class library has them.
    private static readonly ImmutableArray<MetadataReference> _web = LoadWeb();

    private static ImmutableArray<MetadataReference> LoadWeb()
    {
        var web = typeof(Microsoft.AspNetCore.Components.Web.MouseEventArgs).Assembly;
        var names = web.GetReferencedAssemblies().Select(a => a.Name).Append(web.GetName().Name).ToHashSet();
        var present = DiagnosingHarness.WithBlazor(GeneratorHarness.Compile()).References
            .OfType<PortableExecutableReference>().Select(r => r.FilePath).ToHashSet();
        return [.. ((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")!).Split(Path.PathSeparator)
            .Where(p => names.Contains(Path.GetFileNameWithoutExtension(p)) && !present.Contains(p))
            .Select(p => MetadataReference.CreateFromFile(p))];
    }

    public static DiagnosticResult Diagnostic(DiagnosticDescriptor descriptor) => new(descriptor);

    // `razor` paths are rooted ("/Pages/Counter.razor"): a global config section must name an absolute path.
    public static Task VerifyAsync(
        IEnumerable<(string Path, string Text)> razor, IEnumerable<string> csharp, params DiagnosticResult[] expected)
    {
        // The _Imports.razor of the Blazor templates, which brings `@onclick` and `@bind` into scope.
        List<(string Path, string Text)> files = [.. razor, ("/_Imports.razor", "@using Microsoft.AspNetCore.Components.Web\n")];
        var sources = csharp.ToList();
        var test = AnalyzerVerifier<TAnalyzer>.Test<RazorAnalyzerTest>(sources[0]);
        foreach (var source in sources.Skip(1))
        {
            test.TestState.Sources.Add(source);
        }

        test.TestState.AdditionalReferences.AddRange(_web);
        foreach (var (path, text) in files)
        {
            test.TestState.AdditionalFiles.Add((path, text));
        }

        test.TestState.AnalyzerConfigFiles.Add(("/.globalconfig", GlobalConfig(files.Select(f => f.Path))));
        test.CompilerDiagnostics = CompilerDiagnostics.Warnings;
        // The Razor output is the generator's business; what it must do is compile, which the compiler diagnostics check.
        test.TestBehaviors |= TestBehaviors.SkipGeneratedSourcesCheck;
        test.ExpectedDiagnostics.AddRange(expected);
        return test.RunAsync(TestContext.Current.CancellationToken);
    }

    // The SDK passes each .razor file's project-relative path base64-encoded.
    private static string GlobalConfig(IEnumerable<string> paths)
    {
        var config = new StringBuilder("""
            is_global = true
            build_property.RazorConfiguration = Default
            build_property.RazorLangVersion = Latest
            build_property.RootNamespace = App
            build_property.GenerateRazorMetadataSourceChecksumAttributes = false

            """);
        foreach (var path in paths)
        {
            config.Append(CultureInfo.InvariantCulture, $"[{path}]\nbuild_metadata.AdditionalFiles.TargetPath = ")
                .Append(Convert.ToBase64String(Encoding.UTF8.GetBytes(path.TrimStart('/')))).Append('\n');
        }

        return config.ToString();
    }

    // Deviation from a plain verifier test: the verifier compares unmapped spans, which for markup are in the generated
    // .g.cs, while DUCKY009 must surface at the #line-mapped .razor location (SPEC §16.2). So each diagnostic with a
    // mapped path is re-created at that location before the comparison, and the expected results name the .razor file.
    internal sealed class RazorAnalyzerTest : CSharpAnalyzerTest<TAnalyzer, DefaultVerifier>
    {
        protected override IEnumerable<Type> GetSourceGenerators() => [typeof(RazorSourceGenerator)];

        // Nullable enabled, as in the Blazor templates (and GeneratorHarness).
        protected override CompilationOptions CreateCompilationOptions() =>
            ((CSharpCompilationOptions)base.CreateCompilationOptions()).WithNullableContextOptions(NullableContextOptions.Enable);

        protected override ImmutableArray<(Project project, Diagnostic diagnostic)> SortDistinctDiagnostics(
            ImmutableArray<(Project project, Diagnostic diagnostic)> diagnostics) =>
            base.SortDistinctDiagnostics([.. diagnostics.Select(d => (d.project, AtMappedLocation(d.diagnostic)))]);

        private static Diagnostic AtMappedLocation(Diagnostic diagnostic)
        {
            var mapped = diagnostic.Location.GetMappedLineSpan();
            if (!mapped.HasMappedPath)
            {
                return diagnostic;
            }

            var descriptor = diagnostic.Descriptor;
            return Microsoft.CodeAnalysis.Diagnostic.Create(
                diagnostic.Id, descriptor.Category, diagnostic.GetMessage(CultureInfo.InvariantCulture), diagnostic.Severity,
                diagnostic.DefaultSeverity, descriptor.IsEnabledByDefault, diagnostic.WarningLevel, descriptor.Title,
                descriptor.Description, descriptor.HelpLinkUri, Location.Create(mapped.Path, diagnostic.Location.SourceSpan, mapped.Span),
                diagnostic.AdditionalLocations, descriptor.CustomTags, diagnostic.Properties);
        }
    }
}
